import { Key, useEffect, useRef, useState } from "react";

import { StudioProApi } from "@mendix/extensions-api";
import { ConsumedMCPService, Headers, MCPServiceProtocolVersion } from "../../types/consumedMCPService";

import { ContentColumn, ContentColumnLarge, FlexColumn } from "../components/PageContainers";

import { ConstantIcon } from "@mendix/ide-icons/ConstantIcon";
import { TextArea } from "@mendix/ide-ui-components/input/TextArea";
import ComboBoxWithIcon from "../components/ComboBoxWithIcon";
import TextInputLabeled from "../components/TextInputLabeled";
import TextInputWithButton from "../components/TextInputWithButton";
import {
    handleConsumedMCPServiceChangeValue,
    handleEditAuthenticationHeaders,
    handleGetAvailableTools,
    handleSelectAuthenticationMicroflow,
    handleSelectEndpoint,
    handleValidateConsumedMCPService,
} from "./consumedMCPServiceHandlers";

import { MicroflowIcon } from "@mendix/ide-icons/MicroflowIcon";
import { Tool } from "@modelcontextprotocol/sdk/types.js";
import styled from "styled-components";
import { MCP_PROTOCOL_VERSIONS } from "../../constants/mcp";
import { mcpIconBase64 } from "../../icons/toolIcons";
import { componentName } from "../../main";
import { handleShowConstant } from "../../utils/constantUtils";
import { handleShowMicroflow } from "../../utils/microflowUtils";
import ButtonWithLabel from "../components/ButtonWithLabel";
import GroupBox from "../components/GroupBox";
import Table from "../components/Table";
import TextWithIcon from "../components/TextWithIcon";

interface ConsumedMCPServiceProps {
    loadedConsumedMCPService: ConsumedMCPService;
    studioPro: StudioProApi;
    updateStudioProDocument: (consumedMCPService: ConsumedMCPService) => Promise<void>;
}

type ValidationInfo = {
    isValidEndpoint: true | string;
    isValidProtocolVersion: true | string;
    isValidConnectionTimeout: true | string;
    isValidAuthenticationMicroflow: true | string;
};

const initialValidationInfo: ValidationInfo = {
    isValidEndpoint: true,
    isValidProtocolVersion: true,
    isValidConnectionTimeout: true,
    isValidAuthenticationMicroflow: true,
};

const fieldToValidationKey: Partial<Record<keyof ConsumedMCPService, keyof ValidationInfo>> = {
    endpoint: "isValidEndpoint",
    protocolVersion: "isValidProtocolVersion",
    connectionTimeoutSeconds: "isValidConnectionTimeout",
    authenticationMicroflow: "isValidAuthenticationMicroflow",
};

const protocolVersionOptions: { key: MCPServiceProtocolVersion; caption: string }[] = MCP_PROTOCOL_VERSIONS.map(
    (version) => ({
        key: version,
        caption: version,
    })
);

const LastSyncedTimestamp = styled.div`
    color: ${({ theme }) => theme.colorsTextSecondaryDefault};
    font-size: 10px;
`;

const ConsumedMCPServiceEditor: React.FC<ConsumedMCPServiceProps> = ({
    loadedConsumedMCPService,
    studioPro,
    updateStudioProDocument,
}) => {
    const [consumedMCPService, setConsumedMCPService] = useState(loadedConsumedMCPService);
    const [validationInfo, setValidationInfo] = useState(initialValidationInfo);
    const [tools, setTools] = useState<Tool[]>([]);
    const [toolsLoaded, setToolsLoaded] = useState(false);
    const [lastSynched, setLastSynched] = useState<Date | null>(null);
    const [connectionTimeoutInput, setConnectionTimeoutInput] = useState(
        loadedConsumedMCPService.connectionTimeoutSeconds?.toString() ?? ""
    );
    const [headers, setHeaders] = useState<Headers>([]);

    // Ref for debouncing document updates
    const debounceTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);

    // Cleanup debounce timeout on unmount
    useEffect(() => {
        return () => {
            if (debounceTimeout.current) {
                clearTimeout(debounceTimeout.current);
            }
        };
    }, []);

    useEffect(() => {
        // run only on mount
        validateField("endpoint", consumedMCPService);
        validateField("authenticationMicroflow", consumedMCPService);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const validateField = async (field: keyof ConsumedMCPService, updatedConsumedMCPService: ConsumedMCPService) => {
        const validationKey = fieldToValidationKey[field];
        if (validationKey) {
            const validationResult = await handleValidateConsumedMCPService(
                field,
                updatedConsumedMCPService,
                studioPro
            );
            setValidationInfo((prev) => ({ ...prev, [validationKey]: validationResult }));
        }
    };

    // Initial validation - runs only once on mount
    useEffect(() => {
        const triggerValidation = async () => {
            const validationInfo = {
                isValidEndpoint: await handleValidateConsumedMCPService("endpoint", consumedMCPService, studioPro),
                isValidProtocolVersion: await handleValidateConsumedMCPService(
                    "protocolVersion",
                    consumedMCPService,
                    studioPro
                ),
                isValidConnectionTimeout: await handleValidateConsumedMCPService(
                    "connectionTimeoutSeconds",
                    consumedMCPService,
                    studioPro
                ),
                isValidAuthenticationMicroflow: await handleValidateConsumedMCPService(
                    "authenticationMicroflow",
                    consumedMCPService,
                    studioPro
                ),
            };
            setValidationInfo(validationInfo);
        };
        triggerValidation();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const DEBOUNCE_DELAY_MS = 300;
    const debouncedUpdate = (updated: ConsumedMCPService, field: keyof ConsumedMCPService) => {
        if (debounceTimeout.current) clearTimeout(debounceTimeout.current);
        debounceTimeout.current = setTimeout(async () => {
            await updateStudioProDocument(updated);
            await validateField(field, updated);
        }, DEBOUNCE_DELAY_MS);
    };

    //Handlers for selection buttons
    const selectEndpoint = async () => {
        const updatedConsumedMCPService = await handleSelectEndpoint(studioPro, consumedMCPService);
        if (updatedConsumedMCPService) {
            setConsumedMCPService(updatedConsumedMCPService);
            updateStudioProDocument(updatedConsumedMCPService);
            validateField("endpoint", updatedConsumedMCPService);
            setTools([]);
            setToolsLoaded(false);
        }
    };

    const showConstant = async () => {
        if (consumedMCPService.endpoint) {
            handleShowConstant(studioPro, consumedMCPService.endpoint);
        }
    };

    const changeSelectionValue = (field: keyof ConsumedMCPService) => async (key: Key | null) => {
        setConsumedMCPService((prev) => {
            const updated = handleConsumedMCPServiceChangeValue(prev, field, key as string);
            updateStudioProDocument(updated);
            validateField(field, updated);
            return updated;
        });
    };

    // Debounced handlers for text fields
    const onTextAreaChange = (field: keyof ConsumedMCPService) => (value: string) => {
        setConsumedMCPService((prev) => {
            const updated = handleConsumedMCPServiceChangeValue(prev, field, value);
            debouncedUpdate(updated, field);
            return updated;
        });
    };

    const handleConnectionTimeoutChange = (value: string) => {
        if (value !== "" && !/^\d+$/.test(value)) return;
        setConnectionTimeoutInput(value);

        const timeoutValue = value === "" ? undefined : parseInt(value, 10);
        setConsumedMCPService((prev) => {
            const updated = handleConsumedMCPServiceChangeValue(prev, "connectionTimeoutSeconds", timeoutValue);
            debouncedUpdate(updated, "connectionTimeoutSeconds");
            return updated;
        });
    };

    const selectMicroflow = async () => {
        const updatedConsumedMCPService = await handleSelectAuthenticationMicroflow(studioPro, consumedMCPService);
        if (updatedConsumedMCPService) {
            setConsumedMCPService(updatedConsumedMCPService);
            updateStudioProDocument(updatedConsumedMCPService);
            validateField("authenticationMicroflow", updatedConsumedMCPService);
        }
    };

    const showMicroflow = async () => {
        if (consumedMCPService.authenticationMicroflow) {
            handleShowMicroflow(studioPro, consumedMCPService.authenticationMicroflow);
        }
    };

    const viewTools = async () => {
        const hadTools = toolsLoaded;
        setToolsLoaded(false);
        const result = await handleGetAvailableTools(studioPro, consumedMCPService, filterHeaders(headers));
        if (result === undefined) {
            // On failure/cancel: restore the previous table if tools were already shown,
            // otherwise leave toolsLoaded=false so no empty table or stale date is shown.
            if (hadTools) {
                setToolsLoaded(true);
            }
            return;
        }
        setTools(result);
        setToolsLoaded(true);
        setLastSynched(new Date());
    };

    const editAuthenticationHeaders = async () => {
        const updatedHeaders = await handleEditAuthenticationHeaders(studioPro, componentName, headers);

        if (updatedHeaders) {
            setHeaders(updatedHeaders);
        }
    };

    const filterHeaders = (headers: Headers): Headers => headers.filter(([key]) => key.trim() !== "");

    const getHeadersPlaceholder = (headers: Headers) =>
        filterHeaders(headers)
            .map((h) => h[0])
            .join(", ");

    // Determine if there are any validation errors
    const hasValidationErrors = Object.values(validationInfo).some((value) => value !== true);

    return (
        <FlexColumn>
            <ContentColumn>
                <GroupBox label="General">
                    <TextInputLabeled
                        label="Version"
                        ariaLabel="Version"
                        value={consumedMCPService.version === undefined ? "" : consumedMCPService.version}
                        onChange={onTextAreaChange("version")}
                        placeholder="[1.0.0]"
                    />
                    <TextArea
                        label="Documentation"
                        aria-label="Documentation"
                        value={consumedMCPService.documentation}
                        onChange={onTextAreaChange("documentation")}
                        rows={3}
                    />
                </GroupBox>
                <GroupBox label="Configuration">
                    <TextInputWithButton
                        ariaLabel="Endpoint"
                        label="Endpoint"
                        value={consumedMCPService.endpoint ?? ""}
                        icon={consumedMCPService.endpoint ? <ConstantIcon /> : undefined}
                        buttonCaption="Select..."
                        onClick={selectEndpoint}
                        validate={() => validationInfo.isValidEndpoint}
                        buttonCaptionSecondary={consumedMCPService.endpoint ? "Show" : undefined}
                        onClickSecondary={consumedMCPService.endpoint ? showConstant : undefined}
                    />
                    <TextInputWithButton
                        ariaLabel="Credentials microflow"
                        label="Credentials microflow"
                        value={
                            consumedMCPService.authenticationMicroflow ? consumedMCPService.authenticationMicroflow : ""
                        }
                        icon={consumedMCPService.authenticationMicroflow ? <MicroflowIcon /> : undefined}
                        description="Optional: Select a microflow that generates credentials that will be used to authenticate to the MCP server. The microflow needs to return a list of System.HttpHeader objects. Input parameters are not allowed."
                        onClick={selectMicroflow}
                        buttonCaption="Select..."
                        buttonCaptionSecondary={consumedMCPService.authenticationMicroflow ? "Show" : undefined}
                        onClickSecondary={consumedMCPService.authenticationMicroflow ? showMicroflow : undefined}
                        validate={() => validationInfo.isValidAuthenticationMicroflow}
                    />
                    <ComboBoxWithIcon
                        ariaLabel="Protocol version"
                        label="Protocol version"
                        selectedKey={consumedMCPService.protocolVersion}
                        options={protocolVersionOptions}
                        onSelectionChange={changeSelectionValue("protocolVersion")}
                        validate={() => validationInfo.isValidProtocolVersion}
                    />
                    <TextInputLabeled
                        label="Connection timeout (seconds)"
                        ariaLabel="Connection timeout"
                        value={connectionTimeoutInput}
                        description="Optional: Connection timeout controls the maximum time to wait for a response from the MCP server."
                        onChange={handleConnectionTimeoutChange}
                        validate={() => validationInfo.isValidConnectionTimeout}
                    />
                </GroupBox>
            </ContentColumn>
            <ContentColumnLarge>
                <GroupBox label="MCP Tools Playground">
                    <ContentColumn>
                        <TextInputWithButton
                            ariaLabel="MCP Authentication headers"
                            label="Authentication headers"
                            value={getHeadersPlaceholder(headers)}
                            buttonCaption="Edit"
                            onClick={editAuthenticationHeaders}
                            validate={undefined}
                            description="Headers are not stored and only used to explore tools from Studio Pro."
                        />
                    </ContentColumn>
                    <ButtonWithLabel
                        label="Tools"
                        buttonCaption="List tools"
                        onPress={viewTools}
                        disabled={hasValidationErrors}
                    />
                    {toolsLoaded && (
                        <>
                            {lastSynched && (
                                <LastSyncedTimestamp>Last updated: {lastSynched.toLocaleString()}</LastSyncedTimestamp>
                            )}
                            <Table
                                ariaLabel="Tools table"
                                columns={[
                                    {
                                        id: "name",
                                        caption: "Name",
                                        resizable: true,
                                        isRowHeader: true,
                                        defaultWidth: 350,
                                    },
                                    { id: "description", caption: "Description", resizable: true },
                                ]}
                                data={tools.map((tool) => [
                                    <TextWithIcon key={tool.name} icon={mcpIconBase64} text={tool.name} />,
                                    tool.description,
                                ])}
                            />
                        </>
                    )}
                </GroupBox>
            </ContentColumnLarge>
        </FlexColumn>
    );
};

export default ConsumedMCPServiceEditor;
