import { Microflows, ProgressDialogStep, SelectorResult, StudioProApi } from "@mendix/extensions-api";
import { Tool } from "@modelcontextprotocol/sdk/types.js";
import { CommonModelEntities } from "../../constants/genAICommonsEntities";
import { getAvailableMCPTools } from "../../mcp/mcpClient";
import { ConsumedMCPService, Headers } from "../../types/consumedMCPService";
import { getMicroflowByQualifiedName } from "../../utils/microflowUtils";
import { ConstantValidationErrors, validateStringConstant } from "../../utils/validationUtils";

export const handleSelectEndpoint = async (
    studioPro: StudioProApi,
    consumedMCPService: ConsumedMCPService
): Promise<ConsumedMCPService | undefined> => {
    const selectorResult: SelectorResult = await studioPro.ui.elementSelectors.selectDocument({
        allowNone: true,
        query: { elementType: "Constants$Constant" },
    });
    if (selectorResult.status === "ok") {
        return {
            ...consumedMCPService,
            endpoint: selectorResult.selected.module + "." + selectorResult.selected.name,
        };
    }
    if (selectorResult.status === "none") {
        return { ...consumedMCPService, endpoint: "" };
    }
};

export const handleValidateConsumedMCPService = async (
    field: keyof ConsumedMCPService,
    consumedMCPService: ConsumedMCPService,
    studioPro: StudioProApi
): Promise<true | string> => {
    switch (field) {
        case "endpoint": {
            const validationError = await validateStringConstant(studioPro, consumedMCPService.endpoint);

            if (validationError === ConstantValidationErrors.Required) {
                return "Endpoint is required.";
            }

            if (validationError === ConstantValidationErrors.NotFound) {
                return "Selected constant not found. It might have been deleted or renamed. Please update the constant selection.";
            }

            if (validationError === ConstantValidationErrors.InvalidType) {
                return "Selected constant must be of type string.";
            }

            if (validationError === ConstantValidationErrors.PrivateValue) {
                return "Selected constant has a private runtime value, which is currently not supported. Use a public runtime value or remove the constant from the local runtime configuration.";
            }

            if (validationError === ConstantValidationErrors.EmptyValue) {
                return "No value was found for the selected constant. Please set it as part of your local runtime configuration, or set a default value in the constant document.";
            }

            break;
        }

        case "version":
            if (!consumedMCPService.version || consumedMCPService.version.trim() === "") {
                return "Version cannot be empty.";
            }
            break;

        case "protocolVersion":
            if (!consumedMCPService.protocolVersion || consumedMCPService.protocolVersion.trim() === "") {
                return "Protocol version cannot be empty.";
            }
            break;

        case "connectionTimeoutSeconds":
            if (
                consumedMCPService.connectionTimeoutSeconds !== undefined &&
                consumedMCPService.connectionTimeoutSeconds <= 0
            ) {
                return "Connection timeout must be greater than 0 (or empty).";
            }
            break;

        case "authenticationMicroflow": {
            if (consumedMCPService.authenticationMicroflow) {
                const microflow: Microflows.Microflow | null = await getMicroflowByQualifiedName(
                    studioPro,
                    consumedMCPService.authenticationMicroflow || ""
                );
                if (microflow === null) {
                    return "Selected microflow does not exist.";
                }
                const microflowObjects: Microflows.MicroflowObject[] | undefined = microflow.objectCollection.objects;
                const inputParams = microflowObjects?.filter(
                    (obj) => obj.$Type === "Microflows$MicroflowParameterObject"
                );
                if (inputParams && inputParams.length > 0) {
                    return "Authentication microflow cannot have input parameters.";
                }
                if (
                    microflow.microflowReturnType.$Type !== "DataTypes$ListType" ||
                    microflow.microflowReturnType.entity !== CommonModelEntities.HttpHeader
                ) {
                    return "Authentication microflow must return a list of System.HttpHeader objects.";
                }
            }
            break;
        }

        default:
            return true;
    }

    return true;
};

export const handleConsumedMCPServiceChangeValue = (
    consumedMCPService: ConsumedMCPService,
    field: keyof ConsumedMCPService,
    value: string | number | undefined
): ConsumedMCPService => {
    return { ...consumedMCPService, [field]: value };
};

export const handleGetAvailableTools = async (
    studioPro: StudioProApi,
    consumedMCPService: ConsumedMCPService,
    headers: Headers
): Promise<Tool[] | undefined> => {
    let tools: Tool[] | undefined;
    const steps: ProgressDialogStep[] = [
        {
            title: "Getting exposed tools",
            description: "Getting exposed tools",
            action: async () => {
                try {
                    tools = await getAvailableMCPTools(studioPro, consumedMCPService, headers);
                    return true;
                } catch (error) {
                    return error instanceof Error ? error.message : "Failed to load tools.";
                }
            },
        },
    ];

    const progressDialogResult = await studioPro.ui.dialogs.showProgressDialog("Getting exposed tools", steps);
    switch (progressDialogResult.result) {
        case "Success":
            return tools;
        case "UserCancelled":
            return undefined;
        case "Failure": {
            const errorMessage = "Failed to load tools.";
            const errorDetails =
                "Check your connection and make sure your MCP server is available, then try again.\n" +
                (progressDialogResult.failedStep?.error ?? "");
            await studioPro.ui.messageBoxes.show("error", errorMessage, errorDetails);
            return undefined;
        }
    }
};

export const handleSelectAuthenticationMicroflow = async (
    studioPro: StudioProApi,
    consumedMCPService: ConsumedMCPService
): Promise<ConsumedMCPService | null> => {
    const selectorResult: SelectorResult = await studioPro.ui.elementSelectors.selectDocument({
        query: { elementType: "Microflows$Microflow" },
        allowNone: true,
    });
    if (selectorResult.status === "ok") {
        return {
            ...consumedMCPService,
            authenticationMicroflow: selectorResult.selected.module + "." + selectorResult.selected.name,
        };
    }
    if (selectorResult.status === "none") {
        return { ...consumedMCPService, authenticationMicroflow: "" };
    }
    return null;
};

export const handleEditAuthenticationHeaders = async (
    studioPro: StudioProApi,
    componentName: string,
    headers: Headers
): Promise<Headers | undefined> => {
    const result = await studioPro.ui.dialogs.showModal(
        {
            title: "Edit headers",
            contentSize: { height: 500, width: 700 },
        },
        {
            componentName: componentName,
            uiEntrypoint: "mcpAuthenticationHeadersEdit",
            queryParams: {
                headers: encodeURIComponent(JSON.stringify(headers)),
            },
        }
    );

    if (!result) {
        return;
    }

    return result as Headers;
};
