import { StudioProApi } from "@mendix/extensions-api";
import { Client } from "@modelcontextprotocol/sdk/client";
import { applyMiddlewares, createMiddleware } from "@modelcontextprotocol/sdk/client/middleware.js";
import { SSEClientTransport } from "@modelcontextprotocol/sdk/client/sse.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";
import {
    ListToolsRequest,
    ListToolsResultSchema,
    LoggingMessageNotificationSchema,
    ProgressNotificationSchema,
    Tool,
} from "@modelcontextprotocol/sdk/types.js";
import { ILogObj, Logger } from "tslog";
import { createStudioProLogger } from "../config/logger";
import { ConsumedMCPService, Headers as MCPHeaders, MCPServiceProtocolVersion } from "../types/consumedMCPService";
import { getConstantValue } from "../utils/constantUtils";

export interface MCPConnection {
    client: Client;
    transport: StreamableHTTPClientTransport | SSEClientTransport;
    transportType: "streamable-http" | "sse";
}

//Optional notification handlers for MCP client
export interface MCPNotificationHandlers {
    //Handler for server log messages (info, debug, error, etc.)
    onMessage?: (level: string, data: unknown) => void;
    //Handler for progress updates on long-running operations
    onProgress?: (progressToken: string, progress: number, total?: number) => void;
}

/**
 * Create and connect an MCP client with backwards compatibility
 *
 * This client demonstrates backward compatibility with both:
 * 1. Modern servers using Streamable HTTP transport (protocol version 2025-03-26)
 * 2. Older servers using HTTP+SSE transport (protocol version 2024-11-05)
 *
 * Following the MCP specification for backwards compatibility:
 * - Attempts to POST an initialize request to the server URL first (modern transport)
 * - If that fails with 4xx status, falls back to GET request for SSE stream (older transport)
 *
 * @param serverUrl - The URL of the MCP server to connect to
 * @param version - The version of the client application
 * @param logger - Logger instance
 * @param handlers - Optional notification handlers for receiving server notifications
 * @param protocolVersion - Protocol version can be used to determine transport method
 * @returns Promise resolving to the connection object containing client and transport
 */
export async function createMCPClient(
    serverUrl: string,
    version: string,
    logger: Logger<ILogObj>,
    protocolVersion: MCPServiceProtocolVersion,
    headers: MCPHeaders,
    handlers?: MCPNotificationHandlers
): Promise<MCPConnection> {
    logger.debug(`Connecting to server at: ${serverUrl}`);

    const connection = await connectWithMCPServer(serverUrl, version, logger, protocolVersion, headers);

    // Set up notification handlers if provided
    if (handlers?.onMessage) {
        connection.client.setNotificationHandler(LoggingMessageNotificationSchema, (notification) => {
            handlers.onMessage!(notification.params.level, notification.params.data);
        });
    }

    if (handlers?.onProgress) {
        connection.client.setNotificationHandler(ProgressNotificationSchema, (notification) => {
            handlers.onProgress!(
                String(notification.params.progressToken),
                notification.params.progress,
                notification.params.total
            );
        });
    }

    return connection;
}

/**
 * Close an MCP client connection
 *
 * @param connection - The connection object to close
 */
export async function closeMCPClient(connection: MCPConnection, logger: Logger<ILogObj>): Promise<void> {
    logger.debug("Disconnecting from MCP server...");

    // Remove error handler to avoid logging expected abort errors during shutdown
    connection.client.onerror = undefined;

    await connection.transport.close();
    logger.debug("Disconnected from MCP server");
}

async function connectWithSSE(
    client: Client,
    baseUrl: URL,
    authMiddleware: ReturnType<typeof createMiddleware>
): Promise<MCPConnection> {
    const sseTransport = new SSEClientTransport(baseUrl, { fetch: applyMiddlewares(authMiddleware)(fetch) });

    try {
        await client.connect(sseTransport);
    } catch (error) {
        // EventSource automatically reconnects on failure by spec.
        // Close the transport to stop endless reconnection attempts.
        await sseTransport.close().catch(() => {});
        throw error;
    }
    return { client, transport: sseTransport, transportType: "sse" };
}

async function connectWithStreamableHTTP(
    client: Client,
    baseUrl: URL,
    authMiddleware: ReturnType<typeof createMiddleware>
): Promise<MCPConnection> {
    const streamableTransport = new StreamableHTTPClientTransport(baseUrl, {
        fetch: applyMiddlewares(authMiddleware)(fetch),
    });
    await client.connect(streamableTransport);
    return { client, transport: streamableTransport, transportType: "streamable-http" };
}

/**
 * Connect to an MCP server with backwards compatibility
 * Following the spec for client backward compatibility
 */
async function connectWithMCPServer(
    url: string,
    version: string,
    logger: Logger<ILogObj>,
    protocolVersion: MCPServiceProtocolVersion,
    customHeaders: MCPHeaders
): Promise<MCPConnection> {
    const WITHOUT_HEADERS_ERROR_MESSAGE = "Please verify the server URL is correct.";
    const WITH_HEADERS_ERROR_MESSAGE =
        "Please verify the server URL is correct and the attached authentication headers are supported by the server.";
    const SSE_ERROR_MESSAGE = "Could not connect to server using HTTP+SSE transport.";
    const HTTP_SSE_ERROR_MESSAGE = "Could not connect to server with any available transport.";

    const client = new Client({
        name: "Mendix Agent Editor",
        version: version,
    });

    client.onerror = (error) => {
        logger.error("Client error:", error);
    };

    const authMiddleware = createMiddleware(async (next, input, init) => {
        const headers = new Headers(init?.headers);

        customHeaders.forEach(([key, value]) => {
            headers.set(key, value);
        });

        return next(input, { ...init, headers });
    });

    const baseUrl = new URL(url);

    const getErrorMessage = (transport: "SSE" | "HTTP+SSE"): string => {
        let error: string = transport === "SSE" ? SSE_ERROR_MESSAGE : HTTP_SSE_ERROR_MESSAGE;

        if (customHeaders.length > 0) {
            error += ` ${WITH_HEADERS_ERROR_MESSAGE}`;
        } else {
            error += ` ${WITHOUT_HEADERS_ERROR_MESSAGE}`;
        }

        return error;
    };

    // If the protocol version is 2024, skip directly to SSE transport
    if (protocolVersion === "v2024_11_05") {
        logger.debug("Protocol version 2024-11-05 specified, connecting directly with HTTP+SSE transport...");
        try {
            const connection = await connectWithSSE(client, baseUrl, authMiddleware);
            logger.debug("Successfully connected using HTTP+SSE transport.");
            return connection;
        } catch (sseError) {
            logger.error(`Failed to connect using HTTP+SSE transport: ${sseError}`);
            throw new Error(getErrorMessage("SSE"));
        }
    }

    logger.debug("Trying Streamable HTTP transport...");
    try {
        const connection = await connectWithStreamableHTTP(client, baseUrl, authMiddleware);
        logger.debug("Successfully connected using Streamable HTTP transport.");
        return connection;
    } catch (error) {
        logger.debug(`StreamableHttp transport connection failed: ${error}`);
        logger.debug("Falling back to HTTP+SSE transport...");

        try {
            const connection = await connectWithSSE(client, baseUrl, authMiddleware);
            logger.debug("Successfully connected using HTTP+SSE transport.");
            return connection;
        } catch (sseError) {
            logger.error(
                `Failed to connect with either transport method:\n1. Streamable HTTP error: ${error}\n2. SSE error: ${sseError}`
            );
            throw new Error(getErrorMessage("HTTP+SSE"));
        }
    }
}

/**
 * List available tools on the server
 *
 * @param client - The MCP client connection
 * @param logger - Logger instance
 * @returns Promise resolving to array of available tools
 */
export async function listTools(client: Client, logger: Logger<ILogObj>): Promise<Tool[]> {
    try {
        const toolsRequest: ListToolsRequest = {
            method: "tools/list",
            params: {},
        };
        const toolsResult = await client.request(toolsRequest, ListToolsResultSchema);

        logger.debug(`Found ${toolsResult.tools.length} tools`);
        for (const tool of toolsResult.tools) {
            logger.debug(`  - ${tool.name}: ${tool.description}`);
        }

        return toolsResult.tools;
    } catch (error) {
        logger.error(`Tools not supported by this server: ${error}`);
        return [];
    }
}

/**
 * Retrieve the list of tools exposed by an MCP server for a given consumed MCP service.
 *
 * Resolves the endpoint constant value, establishes a connection using the configured
 * protocol version, fetches the available tools, and then closes the connection.
 *
 * @param studioPro - The Studio Pro API instance used for logging and constant resolution
 * @param consumedMCPService - The consumed MCP service configuration containing endpoint, version, and protocol version
 * @returns Promise resolving to an array of available tools, or undefined if the endpoint
 *          constant is missing or has no value
 */
export const getAvailableMCPTools = async (
    studioPro: StudioProApi,
    consumedMCPService: ConsumedMCPService,
    headers: MCPHeaders
): Promise<Tool[] | undefined> => {
    const logger = createStudioProLogger(studioPro);
    const endpointValue = await getConstantValue(studioPro, consumedMCPService.endpoint);

    if (!endpointValue) {
        logger.error(
            `MCP endpoint constant ${consumedMCPService.endpoint} does not have an accessible runtime value or default value.`
        );
        return undefined;
    }

    const mcpConnection: MCPConnection = await createMCPClient(
        endpointValue,
        consumedMCPService.version ?? "",
        logger,
        consumedMCPService.protocolVersion,
        headers
    );

    const tools = await listTools(mcpConnection.client, logger);
    await closeMCPClient(mcpConnection, logger);
    return tools;
};
